/**
 * 墨西哥帅哥，奖池
 */
let jackpotNames = ['Mini','Minor','Major','Grand','MAXI']  //节点名称
cc.Class({
    extends: require("LMSlots_PrizePool_Base"),

    properties: {
        _lastLockJackpot:0,  //最后一个被锁定的jackpot
    },

    start () {
        this._super()
        this.scheduleOnce(()=>{
            if(this.node.y + this.node.height > cc.winSize.height / 2 - 74){
                let length = (this.node.y + this.node.height) - (cc.winSize.height / 2 - 74)
                this.node.scale = 1 - length / this.node.height
            }
        },0);
    },
    
    //各个节点上的解锁/锁定表现
    ShowNodeLockByNode:function(node,bLock,unLockBet,poolType,bInit){
        let targetJpNode = node
        if(targetJpNode){
            let lock_node = targetJpNode.getChildByName('lockbg')
            if(lock_node){
                let jp_title = targetJpNode.getChildByName('spr_title')
                lock_node.active = true
                let un_lock_bet = lock_node.getChildByName('betNum')
                un_lock_bet.getComponent(cc.Label).string = Global.FormatNumToComma(unLockBet)

                let lockSp = lock_node.getChildByName('lock').getComponent(sp.Skeleton)
                if(bLock){
                    lock_node.active = true
                    lockSp.setAnimation(0,"animation",false)
                    lockSp.setCompleteListener(()=>{
                        this.updateJackpotLockAni()
                    })
                    if(poolType < this._lastLockJackpot){
                        this._lastLockJackpot = poolType
                    }
                }
                else{
                    lock_node.active = false
                    if(!bInit){
                        let unlockEffect = targetJpNode.getChildByName('unlock')
                        unlockEffect.active = true
                        let unlockEffectSp = unlockEffect.getComponent(sp.Skeleton)
                        unlockEffectSp.setAnimation(0,"animation0"+(poolType+5),false)
                        unlockEffectSp.setCompleteListener(()=>{
                            unlockEffect.active = false
                        })
                        Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.unlock)
                    }
                    if(poolType >= this._lastLockJackpot){
                        this._lastLockJackpot = poolType+1
                    }
                    this.updateJackpotLockAni()
                }
            }
        }
    },

    /**
     * 更新jockpot锁定节点动画
     */
    updateJackpotLockAni(){
        let safeNode = cc.find('Canvas/safe_node')
        let jpNode = safeNode.getComponentInChildren('LMSlotMachine_PrizePool')
        let tempLastJack = this._lastLockJackpot
        if(tempLastJack === 3){
            tempLastJack++
        }else if(tempLastJack === 5){
            tempLastJack = 3
        }
        if(jpNode){
            for (let i = 0; i < jackpotNames.length; i++) {
                const element = jackpotNames[i];
                let targetJpNode = cc.find('prizePool_'+element,jpNode.node.parent)
                if(targetJpNode){
                    let lock_node = targetJpNode.getChildByName('lockbg')
                    if(lock_node){
                        let lockSp = lock_node.getChildByName('lock').getComponent(sp.Skeleton)
                        if(tempLastJack === i){
                            lockSp.setAnimation(0,"animation",true)
                        }else{
                            lockSp.setAnimation(0,"animation",false)
                            lockSp.clearTracks()
                        }
                        lockSp.setCompleteListener(null)
                    }
                    
                }
            }

        }
    },
    // update (dt) {},
});
