cc.Class({
    extends: require("LMSlots_Logic_Base"),

    properties: {

    },

    // LIFE-CYCLE CALLBACKS:

    // update (dt) {},
    //初始化公共组件
    InitCommComponent:function(){
        this._super()
        let safe_node = cc.find('safe_node',this.node)
        let manage = safe_node.addComponent("SunWuKong_manage")
        cc.vv.gameData.setManage(manage)
        cc.vv.gameData.setPopWinManage(safe_node.getComponentInChildren("SunWuKong_Pop"))
        let node_slots = cc.find('slotsfree',safe_node)
        let script_slots = node_slots.addComponent("SunWuKong_Slotsfree")
        cc.vv.gameData.SetFreeSlotsScript(script_slots)
        let collectScript = cc.find('slots/collectNode',safe_node).addComponent("SunWuKong_collectNode")
        cc.vv.gameData.setCollectNode(collectScript)
    },

    //开始游戏
    StartSlot:function(){
        this._super()
        let script_slots = cc.vv.gameData.GetFreeSlotsScript()
        script_slots.Init()
    },

});
