/**
 * 弹窗管理
 */
cc.Class({
    extends: cc.Component,

    properties: {
        _startAddCoin:false,
    },

    // LIFE-CYCLE CALLBACKS:

    onLoad () {

    },

    start () {

    },

    showWin(){
        let popBg = cc.find("popup",this.node)
        popBg.active = true
        popBg.opacity = 0
        cc.tween(popBg).to(0.3,{opacity:255}).start()
    },

    hideWin(callBack){
        let popBg = cc.find("popup",this.node)
        cc.tween(popBg).to(0.3,{opacity:0}).call(()=>{
            if(callBack){
                callBack()
            }
            popBg.active = false
        }).start()
    },

    awaitTime(time){
        return new Promise((sucess, failed)=>{
            this.scheduleOnce(()=>{
                sucess()
            },time);
        });
    },

    showFreeGameTimes(times){
        return new Promise(async (success,failed)=>{
            Global.SlotsSoundMgr.stopBgm();
            Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.music_FloweryPixie_FreespinStart_view)
            this.showWin()
            let showNode = cc.find("show_freeGameTimes",this.node)
            showNode.active = true
            // let lizi = cc.find("title/lizi",showNode)
            // lizi.active = false
            // this.scheduleOnce(()=>{
            //     lizi.active = true
            //     let liziAnimation = lizi.getChildByName("congratulationsLizi").getComponent(cc.Animation)
            //     liziAnimation.play("congratulationsLizi")
            // },0.5)
            let freeGameTime = cc.find("numBg/num",showNode)
            freeGameTime.getComponent(cc.Label).string = times
            let showNodeAnimation = showNode.getComponent(cc.Animation)
            showNodeAnimation.play("showFreeGameTimes")
            showNodeAnimation.on("finished",()=>{
                showNodeAnimation.off("finished")
                showNodeAnimation.play("idleFreeGameTimes")
                let startButton = cc.find("startBtn",showNode)
                startButton.getComponent(cc.Button).interactable = true
                startButton.off("click");

                let func = async ()=>{
                    startButton.getComponent(cc.Button).interactable = false
                    await this.awaitTime(0.2)
                    showNodeAnimation.play("hideFreeGameTimes")
                    showNodeAnimation.on("finished",()=>{
                        showNodeAnimation.off("finished")
                        showNode.active = false
                        this.hideWin(()=>{
                            success()
                        })
                    })
                }
                cc.vv.gameData.checkAutoPlay(startButton,func)
                startButton.on("click", async ()=>{
                    startButton.stopAllActions();
                    func();
                });
            })
        })
    },

    showFreeGameWinCoin(num,times){
        return new Promise(async (success,failed)=>{
            Global.SlotsSoundMgr.stopBgm();
            Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.music_FloweryPixie_FreespinOver_view)
            this.showWin()
            let showNode = cc.find("show_freeGame_winCoin",this.node)
            showNode.active = true
            // let lizi = cc.find("title/lizi",showNode)
            // lizi.active = false
            // this.scheduleOnce(()=>{
            //     lizi.active = true
            //     let liziAnimation = lizi.getChildByName("congratulationsLizi").getComponent(cc.Animation)
            //     liziAnimation.play("congratulationsLizi")
            // },0.5)
            let coin = cc.find("numBg/num",showNode)
            this._startAddCoin = true
            Global.doRoallNumEff(coin,Math.floor(num*0.1),num,2.5,()=>{
                this._startAddCoin = false
            },null,0,true);
            cc.find("Common-FloweryPixie_zi_1/times",showNode).getComponent(cc.Label).string = times
            let showNodeAnimation = showNode.getComponent(cc.Animation)
            showNodeAnimation.play("showFreeGameWinCoin")
            showNodeAnimation.on("finished",()=>{
                showNodeAnimation.off("finished")
                showNodeAnimation.play("idleFreeGameWinCoin")
                let collectButton = cc.find("collectBtn",showNode)
                collectButton.getComponent(cc.Button).interactable = true
                collectButton.off("click");

                let func = async ()=>{
                    collectButton.getComponent(cc.Button).interactable = false
                    if(this._startAddCoin){
                        this._startAddCoin = false
                        coin.stopAllActions()
                        let winCoinLabel = coin.getComponent(cc.Label)
                        winCoinLabel.string = Global.FormatNumToComma(num)
                    }
                    await this.awaitTime(0.2)
                    showNodeAnimation.play("hideFreeGameWinCoin")
                    showNodeAnimation.on("finished",()=>{
                        showNodeAnimation.off("finished")
                        showNode.active = false
                        this.hideWin(()=>{
                            success()
                        })
                    })
                }
                cc.vv.gameData.checkAutoPlay(collectButton, func);
                collectButton.on("click", async ()=>{
                    collectButton.stopAllActions();
                    func();
                });
            })
        })
    },

    showFreeGameWinFree(times){
        return new Promise(async (success,failed)=>{
            Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.music_FloweryPixie_FreespinStart_view)
            this.showWin()
            let showNode = cc.find("show_freeGameWinFree",this.node)
            showNode.active = true
            // let lizi = cc.find("title/lizi",showNode)
            // lizi.active = false
            // this.scheduleOnce(()=>{
            //     lizi.active = true
            //     let liziAnimation = lizi.getChildByName("congratulationsLizi").getComponent(cc.Animation)
            //     liziAnimation.play("congratulationsLizi")
            // },0.5)
            let freeGameTime = cc.find("numBg/num",showNode)
            freeGameTime.getComponent(cc.Label).string = times
            let showNodeAnimation = showNode.getComponent(cc.Animation)
            showNodeAnimation.play("showFreeGameWinFree")
            showNodeAnimation.on("finished",async ()=>{
                showNodeAnimation.off("finished")
                showNodeAnimation.play("idleFreeGameWinFree")
                await this.awaitTime(2)
                showNodeAnimation.play("hideFreeGameWinFree")
                showNodeAnimation.on("finished",()=>{
                    showNodeAnimation.off("finished")
                    showNode.active = false
                    this.hideWin(()=>{
                        success()
                    })
                })
            })
        })
    },
});
