cc.Class({
    extends: cc.Component,

    properties: {
        _smallHua:[],
        _bigHua:[],
        _numBg:[],
        _click:null,
        _tips:null,
        _huaJin:[],
        _collectCoin:[],
        _unlockBet:[],
        _isunlock:[],
    },

    // LIFE-CYCLE CALLBACKS:

    onLoad () {
        for (let i = 1; i < 4; i++) {
            this._smallHua[i-1] = []
            for (let j = 1; j < 9; j++) {
                let smallHua = cc.find("hua"+i+"/smallFlower"+j,this.node)
                this._smallHua[i-1].push(smallHua)
            }
            this._bigHua.push(cc.find("hua"+i+"/bigFlower",this.node))
            this._numBg.push(cc.find("hua"+i+"/numBg",this.node))
            this._huaJin.push(cc.find("hua"+i,this.node))
        }
        this._click = cc.find("click",this.node)
        this._click.on("click",this.onClickTips,this)
        this._tips = cc.find("tips",this.node.parent)
    },

    onDestroy(){

    },

    start () {

    },

    awaitTime(time){
        return new Promise((sucess, failed)=>{
            this.scheduleOnce(()=>{
                sucess()
            },time);
        });
    },

    /**
     * -- 卷轴上方的花朵信息
     local flowerInfo = {
    betLevel = UnlockBetLevel, -- 解锁列表{3,6,9} 对应3个花朵的解锁等级
    flower1 = { -- 记录花朵上面的金币
        coin = 0,  -- 金币
        restCnt = 8,  -- 剩余次数，如果到0还没有刷新，则清零
    },
    flower2 = {
        coin = 0,
        restCnt = 8,
    },
    flower3 = {
        coin = 0,
        restCnt = 8,
    },
}
     */
    init(flowerInfo){
        let collectCoin = []
        collectCoin.push(flowerInfo.flower1.coin)
        collectCoin.push(flowerInfo.flower2.coin)
        collectCoin.push(flowerInfo.flower3.coin)
        this._collectCoin = collectCoin
        this._unlockBet = flowerInfo.betLevel
        this.initSmallHua(0,flowerInfo.flower1.restCnt)
        this.initSmallHua(1,flowerInfo.flower2.restCnt)
        this.initSmallHua(2,flowerInfo.flower3.restCnt)
        this._isunlock = [true,true,true]
        this.initLockState()
    },

    initLockState(){
        let curBet = cc.vv.gameData.GetBetIdx()
        if(curBet >= this._unlockBet[2]){
            this.initHuaDuo(0,this._collectCoin[0],false)
            this.initHuaDuo(1,this._collectCoin[1],false)
            this.initHuaDuo(2,this._collectCoin[2],false)
        }else if(curBet >= this._unlockBet[1]){
            this.initHuaDuo(0,this._collectCoin[0],false)
            this.initHuaDuo(1,this._collectCoin[1],false)
            this.initHuaDuo(2,this._collectCoin[2],true)
        }else if(curBet >= this._unlockBet[0]){
            this.initHuaDuo(0,this._collectCoin[0],false)
            this.initHuaDuo(1,this._collectCoin[1],true)
            this.initHuaDuo(2,this._collectCoin[2],true)
        }else{
            this.initHuaDuo(0,this._collectCoin[0],true)
            this.initHuaDuo(1,this._collectCoin[1],true)
            this.initHuaDuo(2,this._collectCoin[2],true)
        }
    },

    updateLockState(){
        let curBet = cc.vv.gameData.GetBetIdx()
        if(curBet >= this._unlockBet[2]){
            this.updateHuaDuo(0,this._collectCoin[0],false)
            this.updateHuaDuo(1,this._collectCoin[1],false)
            this.updateHuaDuo(2,this._collectCoin[2],false)
        }else if(curBet >= this._unlockBet[1]){
            this.updateHuaDuo(0,this._collectCoin[0],false)
            this.updateHuaDuo(1,this._collectCoin[1],false)
            this.updateHuaDuo(2,this._collectCoin[2],true)
        }else if(curBet >= this._unlockBet[0]){
            this.updateHuaDuo(0,this._collectCoin[0],false)
            this.updateHuaDuo(1,this._collectCoin[1],true)
            this.updateHuaDuo(2,this._collectCoin[2],true)
        }else{
            this.updateHuaDuo(0,this._collectCoin[0],true)
            this.updateHuaDuo(1,this._collectCoin[1],true)
            this.updateHuaDuo(2,this._collectCoin[2],true)
        }
    },

    getBigHua(index){
        return this._bigHua[index]
    },

    getCoin(index){
        return this._collectCoin[index]
    },

    onClickTips(){
        this._click.getComponent(cc.Button).interactable = false
        this._tips.active = true
        this._tips.scale = 0
        cc.tween(this._tips).to(0.5,{scale:1},{easing:"backOut"})
            .delay(1)
            .to(0.5,{scale:0},{easing:"backIn"})
            .call(()=>{
                this._tips.active = false
                this._click.getComponent(cc.Button).interactable = true
            }).start()
    },

    lockHua(index,isInit = false){
        if(index < 0 || index > 2){
            return
        }
        if(!isInit){
            if(!this._isunlock[index]){
                return
            }
            Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.music_FloweryPixie_BigHua_Close)
        }
        this._isunlock[index] = false
        let bigHua = this._bigHua[index]
        let bigHuaSp = bigHua.getComponent(sp.Skeleton)
        bigHuaSp.setAnimation(0,"yahei",true)
        bigHua.y = 105
        let huajin = this._huaJin[index]
        huajin.color = cc.color(60,60,60)
        let smallHua = this._smallHua[index]
        for (let i = 0; i < smallHua.length; i++) {
            smallHua[i].opacity = 0
        }
        this._numBg[index].active = false
    },

    unlockHua(index,isInit = false){
        if(index < 0 || index > 2){
            return
        }
        if(!isInit){
            if(this._isunlock[index]){
                return
            }
            Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.music_FloweryPixie_BigHua_Open)
        }
        this._isunlock[index] = true
        let smallHua = this._smallHua[index]
        for (let i = 0; i < smallHua.length; i++) {
            smallHua[i].opacity = 255
        }
        let coin = this._collectCoin[index]
        let bigHua = this._bigHua[index]
        let bigHuaSp = bigHua.getComponent(sp.Skeleton)
        if(coin > 0){
            bigHua.y = 120;
            bigHuaSp.setAnimation(0,"kai2",false)
            bigHuaSp.addAnimation(0,"idleframe6",true)
            this._numBg[index].active = true
            cc.find("num",this._numBg[index]).getComponent(cc.Label).string = Global.convertNumToShort(coin,1000,1)
        }else{
            this.closeHuaDuo(index)
        }
        let huajin = this._huaJin[index]
        huajin.color = cc.color(255,255,255)
    },

    hideCoin(index){
        if(this._numBg[index]){
            this._numBg[index].active = false
        }
    },

    closeHuaDuo(index){
        if(index < 0 || index > 2){
            return
        }
        this._numBg[index].active = false
        let smallHua = this._smallHua[index]
        for (let i = 0; i < smallHua.length; i++) {
            smallHua[i].opacity = 0
        }
        let bigHua = this._bigHua[index]
        let bigHuaSp = bigHua.getComponent(sp.Skeleton)
        bigHuaSp.setAnimation(0,"he",false)
        bigHuaSp.addAnimation(0,"idleframe5",true)
        bigHua.y = 105;
        this._collectCoin[index] = 0
    },

    openHuaDuo(index,coin){
        if(index < 0 || index > 2){
            return
        }
        if(this._collectCoin[index] === 0){
            let bigHua = this._bigHua[index]
            bigHua.y = 120
            let bigHuaSp = bigHua.getComponent(sp.Skeleton)
            bigHuaSp.setAnimation(0,"kai2",false)
            bigHuaSp.addAnimation(0,"idleframe6",true)
        }
        this._collectCoin[index] += coin
        this._numBg[index].active = true
        cc.find("num",this._numBg[index]).getComponent(cc.Label).string = Global.convertNumToShort(this._collectCoin[index],1000,1)
        this.resetSmallHua(index)
    },

    initHuaDuo(index,coin,isClose){
        if(index < 0 || index > 2){
            return
        }
        cc.find("num",this._numBg[index]).getComponent(cc.Label).string = Global.convertNumToShort(coin,1000,1)
        if(isClose){
            this.lockHua(index,true)
        }else{
            this.unlockHua(index,true)
        }
    },

    updateHuaDuo(index,coin,isClose){
        if(index < 0 || index > 2){
            return
        }
        cc.find("num",this._numBg[index]).getComponent(cc.Label).string = Global.convertNumToShort(coin,1000,1)
        if(isClose){
            this.lockHua(index)
        }else{
            this.unlockHua(index)
        }
    },

    hideSmallHua(){
        for (let i = 0; i < this._smallHua.length; i++) {
            if(this._collectCoin[i] === 0){
                continue
            }
            if(!this._isunlock[i]){
                continue
            }
            let smallHua = this._smallHua[i]
            for (let i = 0; i < smallHua.length; i++) {
                if(smallHua[i].active){
                    cc.tween(smallHua[i]).to(0.5,{opacity:0}).call(()=>{
                        smallHua[i].active = false
                    }).start()
                    break
                }
            }
        }
    },

    initSmallHua(index,num){
        if(index < 0 || index > 2){
            return
        }
        let smallHua = this._smallHua[index]
        for (let i = 0; i < 8 - num; i++) {
            if(smallHua[i]){
                smallHua[i].active = false
            }
        }
    },

    resetSmallHua(index){
        if(index < 0 || index > 2){
            return
        }
        let smallHua = this._smallHua[index]
        for (let i = 0; i < smallHua.length; i++) {
            smallHua[i].opacity = 255
            smallHua[i].active = true
        }
    },

    checkCloseHuaDuo(){
        for (let i = 0; i < this._smallHua.length; i++) {
            if(!this._isunlock[i]){
                continue
            }
            let coin = this._collectCoin[i]
            if(coin > 0){
                let huaNum = 0
                for (let j = 0; j < this._smallHua[i].length; j++) {
                    if(this._smallHua[i][j].active){
                        huaNum++
                    }
                }
                if(huaNum === 0){
                    this._collectCoin[i] = 0
                    this.closeHuaDuo(i)
                }
            }
        }
    },

    // update (dt) {},

});
